SELECT errand_order_id, feed_time, create_time, price, view_count
FROM errand_feed_index
WHERE state = 'PUBLISHED'



            AND (view_count < #{cursor.viewCount}
                OR (view_count = #{cursor.viewCount} AND create_time < #{cursor.createTime})
                OR (view_count = #{cursor.viewCount} AND create_time = #{cursor.createTime}
                    AND errand_order_id < #{cursor.orderId}))


            AND (feed_time > #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND errand_order_id > #{cursor.orderId}))


            AND (price > #{cursor.price}
                OR (price = #{cursor.price} AND errand_order_id > #{cursor.orderId}))


            AND (price < #{cursor.price}
                OR (price = #{cursor.price} AND errand_order_id < #{cursor.orderId}))


            AND (feed_time < #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND errand_order_id < #{cursor.orderId}))



ORDER BY

    view_count DESC, create_time DESC, errand_order_id DESC
    feed_time ASC, errand_order_id ASC
    price ASC, errand_order_id ASC
    price DESC, errand_order_id DESC
    feed_time DESC, errand_order_id DESC

LIMIT #{limit}
